def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if path.startswith('/'):
        components = split(path)
    else:
        components = split(cwd) + split(path)

    stack = []
    queue = components[:]
    link_count = 0

    while queue:
        comp = queue.pop(0)
        if comp == '..':
            if stack:
                stack.pop()
            continue
        else:
            stack.append(comp)
            current = '/' + '/'.join(stack)
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[current]
                # remove the just-appended component; stack now represents
                # the directory containing the link
                stack.pop()
                if target.startswith('/'):
                    new_components = split(target)
                    stack = []
                else:
                    parent = '/' + '/'.join(stack) if stack else '/'
                    new_components = split(parent) + split(target)
                queue = new_components + queue
                continue

    if not stack:
        return '/'
    else:
        return '/' + '/'.join(stack)

